using FloppyUtils.SourceGen.Ext.Extensions;
using FloppyUtils.SourceGen.Ext.Helpers;
using FloppyUtils.SourceGen.Helpers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace FloppyUtils.SourceGen.Generators;

[Generator]
public sealed class WeakProxyGenerator : IIncrementalGenerator
{
    internal const string Attribute = "FloppyUtils.SourceGen.Attributes.WeakProxyAttribute";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var infos = context.SyntaxProvider.ForAttributeWithMetadataName(
            Attribute,
            static (node, _) => node is StructDeclarationSyntax,
            static (context, token) => context.TargetSymbol is INamedTypeSymbol symbol ? Parse(context, symbol, token) : default
        ).Where(i => i != default);

        context.RegisterSourceOutput(
            infos,
            static (context, item) =>
            {
                if (item.Item1 is { } diag)
                {
                    context.ReportDiagnostic(diag.Create());
                }

                if (item.Item2 is { } info)
                {
                    context.AddSource($"{info.Hierarchy.FullName}.WeakProxy.g.cs", Generate(info, context.CancellationToken));
                }
            }
        );
    }

    internal static (DiagnosticInfo?, Info?) Parse(in GeneratorAttributeSyntaxContext context, INamedTypeSymbol symbol, CancellationToken token)
    {
        using var props = new ImmutableArrayBuilder<(string, string, bool, bool)>();
        using var methods = new ImmutableArrayBuilder<(MethodReturn, string, int, EquatableArray<MethodParam>)>();

        var members = symbol.GetMembers();
        for (int i = 0; i < members.Length; i++)
        {
            var member = members[i];
            if (member.IsStatic || member.DeclaredAccessibility != Accessibility.Public)
            {
                continue;
            }

            switch (member)
            {
                case IPropertySymbol { IsPartialDefinition: true } prop:
                    props.Add((prop.Type.GetNameWithContainingTypeAndNamespace(), prop.Name, prop.GetMethod is not null, prop.SetMethod is not null));
                    break;

                case IMethodSymbol { IsPartialDefinition: true, MethodKind: MethodKind.Ordinary } method:
                    methods.Add((method.GetMethodReturn(), method.Name, i, method.GetMethodParams()));
                    break;
            }
        }

        Info proxy = new(
            symbol.GetHierarchy(),
            props.ToImmutable(),
            methods.ToImmutable()
        );

        return (
            null,
            proxy
        );
    }

    internal static string Generate(Info info, CancellationToken token)
    {
        using var writer = new IndentedTextWriter();
        writer.WriteLine("// <auto-generated/>");
        writer.WriteLine("#nullable enable");

        using (writer.BeginHierarchy(info.Hierarchy, modifiers: "readonly", bases: "global::FloppyUtils.WeakRoot.IProxy"))
        {
            writer.WriteLine("private readonly global::FloppyUtils.WeakRoot _root;");
            writer.WriteLine("private readonly object _value;");
            writer.WriteLine();

            writer.Write("public ");
            writer.Write(info.Hierarchy.Parts[0].Name);
            writer.WriteLine("(global::FloppyUtils.WeakRoot root, object value)");
            writer.WriteLine("{");
            writer.IncreaseIndent();
            writer.WriteLine("_root = root;");
            writer.WriteLine("_value = value;");
            writer.DecreaseIndent();
            writer.WriteLine("}");
            writer.WriteLine();

            writer.WriteLine("global::FloppyUtils.WeakRoot global::FloppyUtils.WeakRoot.IProxy.Root => _root;");
            writer.WriteLine("object global::FloppyUtils.WeakRoot.IProxy.Value => _value;");

            foreach (var prop in info.Props)
            {
                writer.Write("public partial ");
                writer.Write(prop.Type);
                writer.Write(" ");
                writer.WriteLine(prop.Name);
                writer.WriteLine("{");
                writer.IncreaseIndent();

                if (prop.Get)
                {
                    writer.Write("get => (");
                    writer.Write(prop.Type);
                    writer.Write(") _root.GetMemberValue(_value, nameof(");
                    writer.Write(prop.Name);
                    writer.WriteLine("))!;");
                }

                if (prop.Set)
                {
                    writer.Write("set => _root.SetMemberValue(_value, nameof(");
                    writer.Write(prop.Name);
                    writer.WriteLine("), value);");
                }

                writer.DecreaseIndent();
                writer.WriteLine("}");
                writer.WriteLine();
            }

            foreach (var method in info.Methods)
            {
                writer.Write("private delegate ");
                writer.WriteSigReturnType(method.Return);
                writer.Write(" ");
                writer.Write(method.Name);
                writer.Write("Sig");
                writer.Write(method.Index.ToString());
                writer.Write("(object _this");
                if (method.Params.Length != 0)
                {
                    writer.Write(", ");
                    writer.WriteSigParams(method.Params);
                }
                writer.WriteLine(");");

                writer.Write("public partial ");
                writer.WriteSigReturnType(method.Return);
                writer.Write(" ");
                writer.Write(method.Name);
                writer.Write("(");
                writer.WriteSigParams(method.Params);
                writer.Write(") => ");
                writer.Write("_root.GetMethod<");
                writer.Write(method.Name);
                writer.Write("Sig");
                writer.Write(method.Index.ToString());
                writer.Write(">(_value.GetType(), nameof(");
                writer.Write(method.Name);
                writer.Write("))!.Invoke(_value");
                if (method.Params.Length != 0)
                {
                    writer.Write(", ");
                    writer.WriteCallParams(method.Params);
                }
                writer.Write(")");
                writer.WriteLine(";");
            }
        }

        return writer.ToString();
    }

    internal sealed record class Info(
        Hierarchy Hierarchy,
        EquatableArray<(string Type, string Name, bool Get, bool Set)> Props,
        EquatableArray<(MethodReturn Return, string Name, int Index, EquatableArray<MethodParam> Params)> Methods
    );
}
